def isCircle(N, A):
    if N == 0:
        return 0

    graph = {}
    in_degree = {}
    out_degree = {}

    for s in A:
        start = s[0]
        end = s[-1]
        graph[start] = graph.get(start, []) + [end]
        out_degree[start] = out_degree.get(start, 0) + 1
        in_degree[end] = in_degree.get(end, 0) + 1

    for node in graph:
        if out_degree[node] != in_degree.get(node, 0):
            return 0

    start_node = A[0][0]
    visited = set()

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph.get(node, []):
            dfs(neighbor)

    dfs(start_node)

    return 1 if len(visited) == N else 0

